/**
 * File Types Population Script
 *
 * GENERATED FILE - DO NOT EDIT. Regenerate with
 * projects/ores.sql/utility/generate_file_types_populate.py.
 *
 * Seeds the file_types lookup for the system tenant with the 164 kinds of file the
 * official ORE user guide and the 416 shipped ORE run documents name. The canonical
 * name is the one the guide gives, or else the most common name in the samples, and
 * sample_count out of sample_total records how many samples use it. This script is
 * idempotent.
 */

\echo '--- File Types ---'

do $$
declare
    v_sys_tenant uuid := ores_utility_system_tenant_id_fn();
    r record;
begin
    for r in
        select * from (values
        ('setup.calendarAdjustment', null, 'calendarAdjustment', 'input', 'input_document', 'xml', 'calendaradjustment.xsd', null, 'calendaradjustment.xml', 41, 42, 'What it holds: This file calendaradjustment.xml list out all additional holidays and business days that are added to a specified calendar in ORE. These dates would originally be missing from the calendar and has to be added.The general structure is shown in listing the guide. In this example, two additional dates had been added to the calendar "Japan", one additional holiday and one additional business day. If the user is not certain whether the date is already included or not, adding it to the calendaradjustment.xml to be safe won''t raise any errors. A sample calendaradjustment.xml file can be found in the global example input directory. However, it is only used in Example_1. If the parameter BaseCalendar! is provided then a new calendar will be created using the specified calendar as a base, and adding any AdditionalHolidays! or AdditionalBusinessDays!. In the example below a new calendar CUSTOM_Japan! is being created, it will include any additional holidays or business days specified in the original Japan! calendar plus one additional date. If a new calendar is added in this way and the schema is being used to validate XML input, the corresponding calendar name must be prefixed with `CUSTOM_''. From the ORE user guide: Parameter calendarAdjustment includes the calendarAdjustment.xml which lists out additional holidays and business days to be added to specified calendars. The parameter calendarAdjustment of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 1, false, null),
        ('setup.conventionsFile', null, 'conventionsFile', 'input', 'input_document', 'xml', 'conventions.xsd', 'conventions', 'conventions.xml', 404, 414, 'What it holds: The conventions to associate with a set market quotes in the construction of termstructures are specified in another xml file which we will refer to as conventions.xml in the following though the file name can be chosen by the user. Each separate set of conventions is stored in an XML node. The type of conventions that a node holds is determined by the node name. Every node has an Id! node that gives a unique identifier for the convention set. The following sections describe the type of conventions that can be created and the allowed values. Zero Conventions A node with name Zero is used to store conventions for direct zero rate quotes. Direct zero rate quotes can be given with an explicit maturity date or with a tenor and a set of conventions from which the maturity date is deduced. The node for a zero rate quote with an explicit maturity date is shown in Listing the guide. The node for a tenor based zero rate is shown in Listing the guide. The meanings of the various elements in this node are as follows: TenorBased: True if the conventions are for a tenor based zero quote and False if they are for a zero quote with an explicit maturity date. DayCounter: The day count basis associated with the zero rate quote (for choices see section the guide) CompoundingFrequency: The frequency of compounding (Choices are Once, Annual, Semiannual, Quarterly, Bimonthly, Monthly, Weekly, The parameter conventionsFile of the Setup block names it. ORE Studio reads and parses the file into the entities of the conventions configuration when it imports a run, and writes it back from them when it exports one.', 2, false, null),
        ('setup.counterpartyFile', null, 'counterpartyFile', 'input', 'input_document', 'xml', 'counterparty.xsd', null, 'counterparty.xml', 7, 7, 'What it holds: The counterparty information file - counterparty.xml - contains a list of counterparty-level details. The file is written in XML format, with a top-level CounterpartyInformation! node consisting of two children nodes: Counterparties! and Correlations!. Counterparties The Counterparties! node is used to define inputs for each counterparty in the calculations. Each counterparty is then defined with its own Counterparty! node, with the following XML template: The meanings of the various elements of the Counterparty! node are as follows (default input values for certain analytics are specified in their own respective sections, otherwise the defaults below are applicable): CounterpartyId!: The unique identifier for the counterparty. Allowable values: Any string. ClearingCounterparty! [Optional]: Whether the counterparty is a clearing counterparty. Allowable values: Boolean node, allowing Y, N, 1, 0, true, false, etc. The full set of allowable values is given in Table the guide. If left blank or omitted, defaults to False. CreditQuality! [Optional]: Credit quality/rating. Allowable values: HY (high yield), IG (investment grade), NR (not rated). Defaults to NR if left blank or omitted. BaCvaRiskWeight! [Optional]: BA-CVA supervisory risk weight based on sector and credit quality, as defined in Section the guide. This field is only used when calculating BA-CVA or SA-CVA. Allowable The parameter counterpartyFile of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 3, false, null),
        ('setup.currencyConfiguration', null, 'currencyConfiguration', 'input', 'input_document', 'xml', 'currencyconfig.xsd', null, 'currencies.xml', 31, 31, 'What it holds: The currency configuration. It describes each currency the run may meet: its ISO code and number, the number of minor units, the rounding rule, the symbol and the formatting. Amounts are rounded and reported according to it, and a currency that is missing from it cannot be priced. The parameter currencyConfiguration of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 4, false, null),
        ('setup.curveConfigFile', null, 'curveConfigFile', 'input', 'input_document', 'xml', 'curveconfig.xsd', 'curve_configuration', 'curveconfig.xml', 396, 415, 'What it holds: The configuration of various term structures required to price a portfolio is covered in a single configuration file which we will label curveconfig.xml in the following though the file name can be chosen by the user. This configuration determines the composition of Yield curves Default curves Inflation curves Equity forward price curves Swaption volatility structures Cap/Floor volatility structures FX Option volatility structures CDS volatility structures Inflation Cap/Floor price surfaces Equity volatility structures Security spreads and recovery rates Base correlation curves Correlation termstructures Intraday power curves Bond future volatility structures This file also contains other market objects such as FXSpots, Security Spreads and Security Rates which are necessary for the construction of a market. curve_configurations/yieldcurves curve_configurations/default_curves_from_cds curve_configurations/default_curves_other The parameter curveConfigFile of the Setup block names it. ORE Studio reads and parses the file into the entities of the curve_configuration configuration when it imports a run, and writes it back from them when it exports one.', 5, false, null),
        ('setup.iborFallbackConfig', null, 'iborFallbackConfig', 'input', 'input_document', 'xml', 'iborfallbackconfig.xsd', null, 'iborFallbackConfig.xml', 0, 1, 'What it holds: The IBOR fallback configuration. It represents the rules for replacing IBOR reference rates by risk free rates. If no configuration is given, ORE uses a standard one. The parameter iborFallbackConfig of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 6, false, null),
        ('setup.marketConfigFile', null, 'marketConfigFile', 'input', 'input_document', 'xml', 'todaysmarket.xsd', 'todays_market', 'todaysmarket.xml', 385, 413, 'What it holds: This configuration file determines the subset of the ''market'' universe which is going to be built by ORE. It is the user''s responsibility to make sure that this subset is sufficient to cover the portfolio to be analysed. If it is not, the application will complain at run time and exit. We assume that the market configuration is provided in file todaysmarket.xml, however, the file name can be chosen by the user. The file name needs to be entered into the master configuration file ore.xml, see section the guide. The file starts and ends with the opening and closing tags <TodaysMarket> and </TodaysMarket>. The file then contains configuration blocks for Discounting curves Index curves (to project index fixings) Yield curves (for other purposes, e.g. as benchmark curve for bond pricing) Swap index curves (to project Swap rates) FX spot rates Inflation index curves (to project zero or yoy inflation fixings) Equity curves (to project forward prices) Default curves Swaption volatility structures Cap/Floor volatility structures FX volatility structures Inflation Cap/Floor volatility surfaces Equity volatility structures CDS volatility structures Base correlation structures Correlation structures Securities Intraday power price curves The parameter marketConfigFile of the Setup block names it. ORE Studio reads and parses the file into the entities of the todays_market configuration when it imports a run, and writes it back from them when it exports one.', 7, false, null),
        ('setup.pricingEnginesFile', null, 'pricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', 'pricing_engines', 'pricingengine.xml', 402, 416, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The parameter pricingEnginesFile of the Setup block names it. ORE Studio reads and parses the file into the entities of the pricing_engines configuration when it imports a run, and writes it back from them when it exports one.', 8, false, null),
        ('setup.pricingEnginesFileScenario', null, 'pricingEnginesFileScenario', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine.xml', 3, 3, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The parameter pricingEnginesFileScenario of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 9, false, null),
        ('setup.referenceDataFile', null, 'referenceDataFile', 'input', 'input_document', 'xml', 'referencedata.xsd', null, 'referencedata.xml', 6, 13, 'What it holds: Reference Data is used to ease the burden on portfolio xml representation (see ), by taking common elements and storing them as static data. Currently this can be used for Bond Derivatives that require bond static information. Bond reference data is also used to build yield curves fitted to liquid bond prices, see the guide. The allowable types for ReferenceData is Bond static data consists of the Leg data for a given bond. SubType has been added for reporting purposes, to feed into the ISDA product taxonomy, without impact on pricing. Valid SubTypes are: ABS, Corp(orate), Loans, Muni, Sovereign ABX, CMBX, MBX, PrimeX, TRX, iBoxx (in case the Bond represents a Credit or Bond index) Note that the SubType field is currently optional and not covered by schema checks. The parameter referenceDataFile of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 10, false, null),
        ('setup.scriptLibrary', null, 'scriptLibrary', 'input', 'input_document', 'xml', 'scriptlibrary.xsd', null, 'scriptlibrary.xml', 45, 46, 'What it holds: The script library. It holds the scripts that scripted trades run, written in the ORE scripting language, so a payoff that no built-in product covers can be priced. A scripted trade names a script by id. The parameter scriptLibrary of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 11, false, null),
        ('setup.fixingDataFile', null, 'fixingDataFile', 'input', 'data_file', 'txt', null, null, 'fixings.txt', 62, 395, 'What it holds: Fixing History Historical fixings data in the fixings.txt file is given in three columns; Index Name, Fixing Date and Index value. Columns are separated by semicolons ";" or blanks. Fixings are used in cases where the current coupon of a trade has been fixed in the past, or other path dependent features. Allowable values: Any real number (not expressed as a percentage or basis points). An excerpt of a fixings file is shown in Listing the guide. Note that alternative index name formats are used (Table the guide). The parameter fixingDataFile of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 12, false, null),
        ('setup.marketDataFile', null, 'marketDataFile', 'input', 'data_file', 'txt', null, null, 'market.txt', 75, 413, 'What it holds: Market Data In this section we discuss the market data, which enters into the calibration of OREs risk factor evolution models. Market data in the market.txt file is given in three columns; Date, Quote and Quote value. Quote: A generic description that contains Instrument Type and Quote Type, followed by instrument specific descriptions (see the guide ff.). The base of a quote consists of InstType/QuoteType followed by instrument specific information separated by slashes "/". Allowable values for Instrument Types and Quote Types are given in Table the guide. The parameter marketDataFile of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 13, false, null),
        ('setup.portfolioFile', null, 'portfolioFile', 'input', 'data_file', 'xml', 'input.xsd', null, 'portfolio.xml', 173, 388, 'What it holds: The portfolio. It lists the trades to be valued, each with an id, a trade type, the netting set it belongs to, the counterparty and the full instrument data. It is the object every analytic runs over, so the trades in it decide what the reports contain. The parameter portfolioFile of the Setup block names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 14, false, null),
        ('amc.pricingEnginesFile', 'amc', 'pricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine.xml', 1, 1, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The amc analytic values the portfolio with American Monte Carlo. The parameter pricingEnginesFile of the amc analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 15, false, null),
        ('bacva.collateralBalancesFile', 'bacva', 'collateralBalancesFile', 'input', 'input_document', 'xml', 'collateralbalance.xsd', null, 'collateralbalances.xml', 4, 4, 'What it holds: The collateral balances file - collateralbalances.xml - contains the list of collateral balances (i.e. margin amounts and independent amount) under a Credit Support Annex. The balances of each netting set are defined within their own CollateralBalance! node. All of these CollateralBalance! nodes are contained as children of a CollateralBalances! node. The collateral balances are given in the following XML template: The bacva analytic computes the BA-CVA capital from a netting set file and the collateral balances, using saccr for the exposures. The parameter collateralBalancesFile of the bacva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 16, false, null),
        ('bacva.csaFile', 'bacva', 'csaFile', 'input', 'input_document', 'xml', 'nettingsetdefinitions.xsd', null, 'netting.xml', 4, 4, 'What it holds: The netting set definitions file - netting.xml - contains a list of definitions for various ISDA netting agreements. The file is written in XML format. Each netting set is defined within its own NettingSet! node. All of these NettingSet! nodes are contained as children of a NettingSetDefinitions! node. An ISDA agreement which does not contain a Credit Support Annex (CSA). An ISDA agreement which does contain a CSA. Uncollateralised Netting Set If an ISDA agreement does not contain a Credit Support Annex, the portfolio exposures are not eligible for collateralisation. In such a case the netting set can be defined within the following XML template: The bacva analytic computes the BA-CVA capital from a netting set file and the collateral balances, using saccr for the exposures. The parameter csaFile of the bacva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 17, false, null),
        ('calibration.configFile', 'calibration', 'configFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 8, 12, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The calibration analytic calibrates the simulation model to the market. The parameter configFile of the calibration analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 18, false, null),
        ('correlation.marketConfigFile', 'correlation', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 0, 0, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The correlation analytic estimates the correlation of the risk factors from historical scenarios. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. Only a subset of the specification is needed (the one given under Market, see the guide for a detailed description). The parameter marketConfigFile of the correlation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 19, false, null),
        ('correlation.scenarioCorrSimulation', 'correlation', 'scenarioCorrSimulation', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 1, 1, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The correlation analytic estimates the correlation of the risk factors from historical scenarios. The parameter scenarioCorrSimulation of the correlation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 20, false, null),
        ('correlation.sensitivityConfigFile', 'correlation', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 1, 1, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The correlation analytic estimates the correlation of the risk factors from historical scenarios. From the ORE user guide: Sensitivity parameterisation for the sensitivity analysis on asofDate. The parameter sensitivityConfigFile of the correlation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 21, false, null),
        ('crif.marketConfigFile', 'crif', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'crifmarket.xml', 2, 2, 'What it holds: The market description of the CRIF analytic. It lists the market objects needed to compute the ISDA SIMM sensitivities that the CRIF report contains. The crif analytic generates the CRIF, the input of the ISDA SIMM calculation, from a par sensitivity analysis. The parameter marketConfigFile of the crif analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 22, false, null),
        ('crif.sensitivityConfigFile', 'crif', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 2, 2, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The crif analytic generates the CRIF, the input of the ISDA SIMM calculation, from a par sensitivity analysis. The parameter sensitivityConfigFile of the crif analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 23, false, null),
        ('historicalSimulationVar.sensitivityConfigFile', 'historicalSimulationVar', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 1, 1, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The historicalSimulationVar analytic computes value at risk from historical scenarios. The parameter sensitivityConfigFile of the historicalSimulationVar analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 24, false, null),
        ('historicalSimulationVar.simulationConfigFile', 'historicalSimulationVar', 'simulationConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 4, 5, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The historicalSimulationVar analytic computes value at risk from historical scenarios. From the ORE user guide: defines the structure of the simulation market applied in the P&L calculation, e.g. discount and index curves, yield curve tenor points, FX pairs, etc. The parameter simulationConfigFile of the historicalSimulationVar analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 25, false, null),
        ('parStressConversion.marketConfigFile', 'parStressConversion', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 1, 1, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The parStressConversion analytic converts a stress given on par rates into a stress on zero rates. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. Only a subset of the specification is needed (the one given under Market, see the guide for a detailed description). The parameter marketConfigFile of the parStressConversion analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 26, false, null),
        ('parStressConversion.pricingEnginesFile', 'parStressConversion', 'pricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine.xml', 1, 1, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The parStressConversion analytic converts a stress given on par rates into a stress on zero rates. From the ORE user guide: Configuration file for the pricing engines to be used for sensitivity calculation. The parameter pricingEnginesFile of the parStressConversion analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 27, false, null),
        ('parStressConversion.sensitivityConfigFile', 'parStressConversion', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 1, 1, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The parStressConversion analytic converts a stress given on par rates into a stress on zero rates. From the ORE user guide: Configuration file for the sensitivity calculation, see section the guide. The parameter sensitivityConfigFile of the parStressConversion analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 28, false, null),
        ('parStressConversion.stressConfigFile', 'parStressConversion', 'stressConfigFile', 'input', 'input_document', 'xml', 'stress.xsd', null, 'stresstest.xml', 0, 1, 'What it holds: Stress tests can be applied in ORE to the same market segments and with same granularity as described in the sensitivity section the guide. This file stressconfig.xml specifies how stress tests can be configured. The general structure is shown in listing the guide. In this example, two zero stress scenarios "parallel_rates" and "twist" and one par rate "par_parallel" are defined. Each scenario definition contains the market components to be shifted in this scenario in a similar syntax that is also used for the sensitivity configuration, see the guide. In addition to the "Absolute" and "Relative" shift types defined in sensitivity configuration, stress tests allow an "EqualTo" shift type. In this case, the user provides the values that the curve should be shifted to. In the case of Discount, Yield, Index curves, and Survival Probabilities, an additional field "ShiftingZeros" is required to indicate if the given shifted values are zero rates (true) or discount rates (false). The parStressConversion analytic converts a stress given on par rates into a stress on zero rates. From the ORE user guide: Stress Scenario definition, see section the guide The parameter stressConfigFile of the parStressConversion analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 29, false, null),
        ('parStressConversion.stressZeroScenarioDataFile', 'parStressConversion', 'stressZeroScenarioDataFile', 'input', 'input_document', 'xml', null, null, 'results.xml', 1, 1, 'What it holds: The zero stress scenario data that the par stress conversion writes and the stress analytic reads. It holds the stress scenarios expressed as shifts of zero rates. The parStressConversion analytic converts a stress given on par rates into a stress on zero rates. From the ORE user guide: In the latter par stress case, the last parameter (stressZeroScenarioDataFile) causes exporting equivalent stress test definitions in the "raw" domain. The parameter stressZeroScenarioDataFile of the parStressConversion analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 30, false, null),
        ('pfe.csaFile', 'pfe', 'csaFile', 'input', 'input_document', 'xml', 'nettingsetdefinitions.xsd', null, 'netting.xml', 1, 1, 'What it holds: The netting set definitions file - netting.xml - contains a list of definitions for various ISDA netting agreements. The file is written in XML format. Each netting set is defined within its own NettingSet! node. All of these NettingSet! nodes are contained as children of a NettingSetDefinitions! node. An ISDA agreement which does not contain a Credit Support Annex (CSA). An ISDA agreement which does contain a CSA. Uncollateralised Netting Set If an ISDA agreement does not contain a Credit Support Annex, the portfolio exposures are not eligible for collateralisation. In such a case the netting set can be defined within the following XML template: The pfe analytic computes the potential future exposure profiles. From the ORE user guide: Netting set definitions file covering CSA details such as margining frequency, thresholds, minimum transfer amounts, margin period of risk The parameter csaFile of the pfe analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 31, false, null),
        ('pnl.conventionsMporFile', 'pnl', 'conventionsMporFile', 'input', 'input_document', 'xml', 'conventions.xsd', null, 'conventions.xml', 3, 3, 'What it holds: The conventions to associate with a set market quotes in the construction of termstructures are specified in another xml file which we will refer to as conventions.xml in the following though the file name can be chosen by the user. Each separate set of conventions is stored in an XML node. The type of conventions that a node holds is determined by the node name. Every node has an Id! node that gives a unique identifier for the convention set. The following sections describe the type of conventions that can be created and the allowed values. Zero Conventions A node with name Zero is used to store conventions for direct zero rate quotes. Direct zero rate quotes can be given with an explicit maturity date or with a tenor and a set of conventions from which the maturity date is deduced. The node for a zero rate quote with an explicit maturity date is shown in Listing the guide. The node for a tenor based zero rate is shown in Listing the guide. The meanings of the various elements in this node are as follows: TenorBased: True if the conventions are for a tenor based zero quote and False if they are for a zero quote with an explicit maturity date. DayCounter: The day count basis associated with the zero rate quote (for choices see section the guide) CompoundingFrequency: The frequency of compounding (Choices are Once, Annual, Semiannual, Quarterly, Bimonthly, Monthly, Weekly, The pnl analytic computes a single period profit and loss between the as-of date and a later date. From the ORE user guide: Conventions applied at the mporDate The parameter conventionsMporFile of the pnl analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 32, false, null),
        ('pnl.curveConfigMporFile', 'pnl', 'curveConfigMporFile', 'input', 'input_document', 'xml', 'curveconfig.xsd', null, 'curveconfig.xml', 3, 3, 'What it holds: The configuration of various term structures required to price a portfolio is covered in a single configuration file which we will label curveconfig.xml in the following though the file name can be chosen by the user. This configuration determines the composition of Yield curves Default curves Inflation curves Equity forward price curves Swaption volatility structures Cap/Floor volatility structures FX Option volatility structures CDS volatility structures Inflation Cap/Floor price surfaces Equity volatility structures Security spreads and recovery rates Base correlation curves Correlation termstructures Intraday power curves Bond future volatility structures This file also contains other market objects such as FXSpots, Security Spreads and Security Rates which are necessary for the construction of a market. curve_configurations/yieldcurves curve_configurations/default_curves_from_cds curve_configurations/default_curves_other The pnl analytic computes a single period profit and loss between the as-of date and a later date. The parameter curveConfigMporFile of the pnl analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 33, false, null),
        ('pnl.simulationConfigFile', 'pnl', 'simulationConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 3, 3, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The pnl analytic computes a single period profit and loss between the as-of date and a later date. The parameter simulationConfigFile of the pnl analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 34, false, null),
        ('pnlExplain.conventionsMporFile', 'pnlExplain', 'conventionsMporFile', 'input', 'input_document', 'xml', 'conventions.xsd', null, 'conventions.xml', 5, 5, 'What it holds: The conventions to associate with a set market quotes in the construction of termstructures are specified in another xml file which we will refer to as conventions.xml in the following though the file name can be chosen by the user. Each separate set of conventions is stored in an XML node. The type of conventions that a node holds is determined by the node name. Every node has an Id! node that gives a unique identifier for the convention set. The following sections describe the type of conventions that can be created and the allowed values. Zero Conventions A node with name Zero is used to store conventions for direct zero rate quotes. Direct zero rate quotes can be given with an explicit maturity date or with a tenor and a set of conventions from which the maturity date is deduced. The node for a zero rate quote with an explicit maturity date is shown in Listing the guide. The node for a tenor based zero rate is shown in Listing the guide. The meanings of the various elements in this node are as follows: TenorBased: True if the conventions are for a tenor based zero quote and False if they are for a zero quote with an explicit maturity date. DayCounter: The day count basis associated with the zero rate quote (for choices see section the guide) CompoundingFrequency: The frequency of compounding (Choices are Once, Annual, Semiannual, Quarterly, Bimonthly, Monthly, Weekly, The pnlExplain analytic explains that profit and loss in terms of raw or par sensitivities. From the ORE user guide: Conventions applied at the mporDate The parameter conventionsMporFile of the pnlExplain analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 35, false, null),
        ('pnlExplain.curveConfigMporFile', 'pnlExplain', 'curveConfigMporFile', 'input', 'input_document', 'xml', 'curveconfig.xsd', null, 'curveconfig.xml', 5, 5, 'What it holds: The configuration of various term structures required to price a portfolio is covered in a single configuration file which we will label curveconfig.xml in the following though the file name can be chosen by the user. This configuration determines the composition of Yield curves Default curves Inflation curves Equity forward price curves Swaption volatility structures Cap/Floor volatility structures FX Option volatility structures CDS volatility structures Inflation Cap/Floor price surfaces Equity volatility structures Security spreads and recovery rates Base correlation curves Correlation termstructures Intraday power curves Bond future volatility structures This file also contains other market objects such as FXSpots, Security Spreads and Security Rates which are necessary for the construction of a market. curve_configurations/yieldcurves curve_configurations/default_curves_from_cds curve_configurations/default_curves_other The pnlExplain analytic explains that profit and loss in terms of raw or par sensitivities. The parameter curveConfigMporFile of the pnlExplain analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 36, false, null),
        ('pnlExplain.sensitivityConfigFile', 'pnlExplain', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 5, 5, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The pnlExplain analytic explains that profit and loss in terms of raw or par sensitivities. From the ORE user guide: Sensitivity parameterisation for the sensitivity analysis on asofDate The parameter sensitivityConfigFile of the pnlExplain analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 37, false, null),
        ('pnlExplain.simulationConfigFile', 'pnlExplain', 'simulationConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 5, 5, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The pnlExplain analytic explains that profit and loss in terms of raw or par sensitivities. The parameter simulationConfigFile of the pnlExplain analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 38, false, null),
        ('saccr.collateralBalancesFile', 'saccr', 'collateralBalancesFile', 'input', 'input_document', 'xml', 'collateralbalance.xsd', null, 'collateralbalances.xml', 3, 3, 'What it holds: The collateral balances file - collateralbalances.xml - contains the list of collateral balances (i.e. margin amounts and independent amount) under a Credit Support Annex. The balances of each netting set are defined within their own CollateralBalance! node. All of these CollateralBalance! nodes are contained as children of a CollateralBalances! node. The collateral balances are given in the following XML template: The saccr analytic computes the SA-CCR capital, from a netting set file and the collateral balances. The parameter collateralBalancesFile of the saccr analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 39, false, null),
        ('saccr.csaFile', 'saccr', 'csaFile', 'input', 'input_document', 'xml', 'nettingsetdefinitions.xsd', null, 'netting.xml', 3, 3, 'What it holds: The netting set definitions file - netting.xml - contains a list of definitions for various ISDA netting agreements. The file is written in XML format. Each netting set is defined within its own NettingSet! node. All of these NettingSet! nodes are contained as children of a NettingSetDefinitions! node. An ISDA agreement which does not contain a Credit Support Annex (CSA). An ISDA agreement which does contain a CSA. Uncollateralised Netting Set If an ISDA agreement does not contain a Credit Support Annex, the portfolio exposures are not eligible for collateralisation. In such a case the netting set can be defined within the following XML template: The saccr analytic computes the SA-CCR capital, from a netting set file and the collateral balances. The parameter csaFile of the saccr analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 40, false, null),
        ('scenario.simulationConfigFile', 'scenario', 'simulationConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 3, 3, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The scenario analytic exports the base scenario of the simulation market as a file. The parameter simulationConfigFile of the scenario analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 41, false, null),
        ('scenarioGeneration.simulationConfigFile', 'scenarioGeneration', 'simulationConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 1, 3, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The scenarioGeneration analytic generates market scenarios, for example stress scenarios. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. The parameter simulationConfigFile of the scenarioGeneration analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 42, false, null),
        ('scenarioGeneration.stressConfigFile', 'scenarioGeneration', 'stressConfigFile', 'input', 'input_document', 'xml', 'stress.xsd', null, 'stresstest.xml', 1, 1, 'What it holds: Stress tests can be applied in ORE to the same market segments and with same granularity as described in the sensitivity section the guide. This file stressconfig.xml specifies how stress tests can be configured. The general structure is shown in listing the guide. In this example, two zero stress scenarios "parallel_rates" and "twist" and one par rate "par_parallel" are defined. Each scenario definition contains the market components to be shifted in this scenario in a similar syntax that is also used for the sensitivity configuration, see the guide. In addition to the "Absolute" and "Relative" shift types defined in sensitivity configuration, stress tests allow an "EqualTo" shift type. In this case, the user provides the values that the curve should be shifted to. In the case of Discount, Yield, Index curves, and Survival Probabilities, an additional field "ShiftingZeros" is required to indicate if the given shifted values are zero rates (true) or discount rates (false). The scenarioGeneration analytic generates market scenarios, for example stress scenarios. The parameter stressConfigFile of the scenarioGeneration analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 43, false, null),
        ('sensitivity.marketConfigFile', 'sensitivity', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 63, 76, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. Only a subset of the specification is needed (the one given under Market, see the guide for a detailed description). The parameter marketConfigFile of the sensitivity analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 44, false, null),
        ('sensitivity.pricingEnginesFile', 'sensitivity', 'pricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine.xml', 69, 76, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. From the ORE user guide: Configuration file for the pricing engines to be used for sensitivity calculation. The parameter pricingEnginesFile of the sensitivity analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 45, false, null),
        ('sensitivity.sensitivityConfigFile', 'sensitivity', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 70, 76, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. From the ORE user guide: Configuration file for the sensitivity calculation, see section the guide. The parameter sensitivityConfigFile of the sensitivity analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 46, false, null),
        ('sensitivity.stressConfigFile', 'sensitivity', 'stressConfigFile', 'input', 'input_document', 'xml', 'stress.xsd', null, 'stresstest.xml', 1, 4, 'What it holds: Stress tests can be applied in ORE to the same market segments and with same granularity as described in the sensitivity section the guide. This file stressconfig.xml specifies how stress tests can be configured. The general structure is shown in listing the guide. In this example, two zero stress scenarios "parallel_rates" and "twist" and one par rate "par_parallel" are defined. Each scenario definition contains the market components to be shifted in this scenario in a similar syntax that is also used for the sensitivity configuration, see the guide. In addition to the "Absolute" and "Relative" shift types defined in sensitivity configuration, stress tests allow an "EqualTo" shift type. In this case, the user provides the values that the curve should be shifted to. In the case of Discount, Yield, Index curves, and Survival Probabilities, an additional field "ShiftingZeros" is required to indicate if the given shifted values are zero rates (true) or discount rates (false). The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. The parameter stressConfigFile of the sensitivity analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 47, false, null),
        ('sensitivity.stressZeroScenarioDataFile', 'sensitivity', 'stressZeroScenarioDataFile', 'input', 'input_document', 'xml', null, null, 'zeroStressScenarioData.xml', 1, 1, 'What it holds: The zero stress scenario data. It holds the stress scenarios already expressed as shifts of zero rates, which the stress analytic applies directly to the market. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. The parameter stressZeroScenarioDataFile of the sensitivity analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 48, false, null),
        ('sensitivityStress.marketConfigFile', 'sensitivityStress', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 0, 1, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The sensitivityStress analytic computes sensitivities in a stressed market. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. Only a subset of the specification is needed (the one given under Market, see the guide for a detailed description). The parameter marketConfigFile of the sensitivityStress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 49, false, null),
        ('sensitivityStress.sensitivityConfigFile', 'sensitivityStress', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 0, 1, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The sensitivityStress analytic computes sensitivities in a stressed market. From the ORE user guide: Configuration file for the sensitivity calculation, see section the guide. The parameter sensitivityConfigFile of the sensitivityStress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 50, false, null),
        ('sensitivityStress.stressConfigFile', 'sensitivityStress', 'stressConfigFile', 'input', 'input_document', 'xml', 'stress.xsd', null, 'stresstest.xml', 0, 1, 'What it holds: Stress tests can be applied in ORE to the same market segments and with same granularity as described in the sensitivity section the guide. This file stressconfig.xml specifies how stress tests can be configured. The general structure is shown in listing the guide. In this example, two zero stress scenarios "parallel_rates" and "twist" and one par rate "par_parallel" are defined. Each scenario definition contains the market components to be shifted in this scenario in a similar syntax that is also used for the sensitivity configuration, see the guide. In addition to the "Absolute" and "Relative" shift types defined in sensitivity configuration, stress tests allow an "EqualTo" shift type. In this case, the user provides the values that the curve should be shifted to. In the case of Discount, Yield, Index curves, and Survival Probabilities, an additional field "ShiftingZeros" is required to indicate if the given shifted values are zero rates (true) or discount rates (false). The sensitivityStress analytic computes sensitivities in a stressed market. From the ORE user guide: Stress Scenario definition, see section the guide The parameter stressConfigFile of the sensitivityStress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 51, false, null),
        ('simm.simmCalibration', 'simm', 'simmCalibration', 'input', 'input_document', 'xml', 'simmcalibration.xsd', null, 'simm_calibration.xml', 4, 4, 'What it holds: The SIMM calibration. It holds the risk weights, the correlations and the concentration thresholds of a SIMM version, so the simm analytic can add a version or override one of the versions ORE supports. When it is given it overrides the version parameter. The simm analytic computes initial margin with ISDA''s Standard Initial Margin Model from a CRIF. The parameter simmCalibration of the simm analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 52, false, null),
        ('simulation.amcCgPricingEnginesFile', 'simulation', 'amcCgPricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine_amccg.xml', 19, 19, 'What it holds: The pricing engines for American Monte Carlo on a computation graph. It maps the products to engines that record their payoff as a graph, which allows exposure and sensitivities by algorithmic differentiation. The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter amcCgPricingEnginesFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 53, false, null),
        ('simulation.amcPricingEnginesFile', 'simulation', 'amcPricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine_amc.xml', 53, 65, 'What it holds: The pricing engines for American Monte Carlo. It maps the products that are valued by regression on the simulated paths to their AMC engines, so that exposure simulation can value early exercise and path dependent trades. The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter amcPricingEnginesFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 54, false, null),
        ('simulation.pricingEnginesFile', 'simulation', 'pricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine.xml', 248, 261, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter pricingEnginesFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 55, false, null),
        ('simulation.simulationConfigFile', 'simulation', 'simulationConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 128, 257, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter simulationConfigFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 56, false, null),
        ('simulation.simulationMarketFile', 'simulation', 'simulationMarketFile', 'input', 'input_document', 'xml', null, null, 'simulationmarket.xml', 5, 5, 'What it holds: The market part of a simulation configuration. It lists the simulated market objects, which curves, volatilities and FX rates are evolved, and the tenors and strikes at which each is represented. It is kept apart so that several simulations can share one market definition. The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter simulationMarketFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 57, false, null),
        ('simulation.simulationModelFile', 'simulation', 'simulationModelFile', 'input', 'input_document', 'xml', null, null, 'simulationmodels.xml', 5, 5, 'What it holds: The model part of a simulation configuration. It holds the models and their calibration settings, so that the model choice can change without touching the market or the parameters. The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter simulationModelFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 58, false, null),
        ('simulation.simulationParamFile', 'simulation', 'simulationParamFile', 'input', 'input_document', 'xml', null, null, 'simulationparams.xml', 5, 5, 'What it holds: The parameter part of a simulation configuration. It holds the time grid, the number of samples and the other settings that control the run, apart from the models and the market. The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter simulationParamFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 59, false, null),
        ('simulation.xvaCgSensitivityConfigFile', 'simulation', 'xvaCgSensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'xvasensiconfig.xml', 6, 6, 'What it holds: The sensitivity configuration of the computation graph XVA run. It lists the risk factors for which the XVA sensitivities are taken by differentiating the recorded graph. The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter xvaCgSensitivityConfigFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 60, false, null),
        ('stress.marketConfigFile', 'stress', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 14, 20, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The stress analytic revalues the portfolio under stress scenarios. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. Only a subset of the specification is needed (the one given under Market, see the guide for a detailed description). The parameter marketConfigFile of the stress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 61, false, null),
        ('stress.pricingEnginesFile', 'stress', 'pricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine.xml', 17, 17, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The stress analytic revalues the portfolio under stress scenarios. From the ORE user guide: Configuration file for the pricing engines to be used for sensitivity calculation. The parameter pricingEnginesFile of the stress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 62, false, null),
        ('stress.sensitivityConfigFile', 'stress', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 7, 8, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The stress analytic revalues the portfolio under stress scenarios. The parameter sensitivityConfigFile of the stress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 63, false, null),
        ('stress.stressConfigFile', 'stress', 'stressConfigFile', 'input', 'input_document', 'xml', 'stress.xsd', null, 'stresstest.xml', 15, 19, 'What it holds: Stress tests can be applied in ORE to the same market segments and with same granularity as described in the sensitivity section the guide. This file stressconfig.xml specifies how stress tests can be configured. The general structure is shown in listing the guide. In this example, two zero stress scenarios "parallel_rates" and "twist" and one par rate "par_parallel" are defined. Each scenario definition contains the market components to be shifted in this scenario in a similar syntax that is also used for the sensitivity configuration, see the guide. In addition to the "Absolute" and "Relative" shift types defined in sensitivity configuration, stress tests allow an "EqualTo" shift type. In this case, the user provides the values that the curve should be shifted to. In the case of Discount, Yield, Index curves, and Survival Probabilities, an additional field "ShiftingZeros" is required to indicate if the given shifted values are zero rates (true) or discount rates (false). The stress analytic revalues the portfolio under stress scenarios. From the ORE user guide: Stress Scenario definition, see section the guide The parameter stressConfigFile of the stress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 64, false, null),
        ('stress.stressZeroScenarioDataFile', 'stress', 'stressZeroScenarioDataFile', 'input', 'input_document', 'xml', null, null, 'zeroStressScenarioData.xml', 3, 4, 'What it holds: The zero stress scenario data. It holds the stress scenarios already expressed as shifts of zero rates, which the stress analytic applies directly to the market. The stress analytic revalues the portfolio under stress scenarios. From the ORE user guide: In the latter par stress case, the last parameter (stressZeroScenarioDataFile) causes exporting equivalent stress test definitions in the "raw" domain. The parameter stressZeroScenarioDataFile of the stress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 65, false, null),
        ('xva.collateralBalancesFile', 'xva', 'collateralBalancesFile', 'input', 'input_document', 'xml', 'collateralbalance.xsd', null, 'collateralbalances.xml', 23, 23, 'What it holds: The collateral balances file - collateralbalances.xml - contains the list of collateral balances (i.e. margin amounts and independent amount) under a Credit Support Annex. The balances of each netting set are defined within their own CollateralBalance! node. All of these CollateralBalance! nodes are contained as children of a CollateralBalances! node. The collateral balances are given in the following XML template: The xva analytic computes the exposure profiles and the valuation adjustments. From the ORE user guide: References an xml file that contains current VM and IM balances by netting set The parameter collateralBalancesFile of the xva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 66, false, null),
        ('xva.creditMigrationConfig', 'xva', 'creditMigrationConfig', 'input', 'input_document', 'xml', 'creditsimulation.xsd', null, 'creditsimulation.xml', 2, 14, 'What it holds: The credit simulation configuration. It defines the credit migration model, the rating states and the transition matrices that the XVA analytic uses to simulate defaults and rating changes along the paths. The xva analytic computes the exposure profiles and the valuation adjustments. The parameter creditMigrationConfig of the xva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 67, false, null),
        ('xva.csaFile', 'xva', 'csaFile', 'input', 'input_document', 'xml', 'nettingsetdefinitions.xsd', null, 'netting.xml', 213, 252, 'What it holds: The netting set definitions file - netting.xml - contains a list of definitions for various ISDA netting agreements. The file is written in XML format. Each netting set is defined within its own NettingSet! node. All of these NettingSet! nodes are contained as children of a NettingSetDefinitions! node. An ISDA agreement which does not contain a Credit Support Annex (CSA). An ISDA agreement which does contain a CSA. Uncollateralised Netting Set If an ISDA agreement does not contain a Credit Support Annex, the portfolio exposures are not eligible for collateralisation. In such a case the netting set can be defined within the following XML template: The xva analytic computes the exposure profiles and the valuation adjustments. From the ORE user guide: Netting set definitions file covering CSA details such as margining frequency, thresholds, minimum transfer amounts, margin period of risk The parameter csaFile of the xva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 68, false, null),
        ('xva.scenarioCorrSimulation', 'xva', 'scenarioCorrSimulation', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 0, 1, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The xva analytic computes the exposure profiles and the valuation adjustments. The parameter scenarioCorrSimulation of the xva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 69, false, null),
        ('xva.sensitivityConfigFile', 'xva', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 1, 1, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The xva analytic computes the exposure profiles and the valuation adjustments. The parameter sensitivityConfigFile of the xva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 70, false, null),
        ('xva.simulationConfigFile', 'xva', 'simulationConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 0, 1, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The xva analytic computes the exposure profiles and the valuation adjustments. The parameter simulationConfigFile of the xva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 71, false, null),
        ('xvaExplain.marketConfigFile', 'xvaExplain', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 1, 2, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The xvaExplain analytic computes the market implied change of the value adjustments between two evaluation dates. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. Only a subset of the specification is needed (the one given under Market, see the guide for a detailed description). The parameter marketConfigFile of the xvaExplain analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 72, false, null),
        ('xvaExplain.sensitivityConfigFile', 'xvaExplain', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity_stress.xml', 1, 2, 'What it holds: A sensitivity configuration for the stressed runs. It lists the risk factors to bump in the stressed market and uses a shift size that suits the stress, so the stressed sensitivities are computed on the stressed market. The xvaExplain analytic computes the market implied change of the value adjustments between two evaluation dates. From the ORE user guide: Configuration file for the sensitivity calculation, see section the guide. The parameter sensitivityConfigFile of the xvaExplain analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 73, false, null),
        ('xvaExplain.stressConfigFile', 'xvaExplain', 'stressConfigFile', 'input', 'input_document', 'xml', 'stress.xsd', null, 'stresstest.xml', 1, 1, 'What it holds: Stress tests can be applied in ORE to the same market segments and with same granularity as described in the sensitivity section the guide. This file stressconfig.xml specifies how stress tests can be configured. The general structure is shown in listing the guide. In this example, two zero stress scenarios "parallel_rates" and "twist" and one par rate "par_parallel" are defined. Each scenario definition contains the market components to be shifted in this scenario in a similar syntax that is also used for the sensitivity configuration, see the guide. In addition to the "Absolute" and "Relative" shift types defined in sensitivity configuration, stress tests allow an "EqualTo" shift type. In this case, the user provides the values that the curve should be shifted to. In the case of Discount, Yield, Index curves, and Survival Probabilities, an additional field "ShiftingZeros" is required to indicate if the given shifted values are zero rates (true) or discount rates (false). The xvaExplain analytic computes the market implied change of the value adjustments between two evaluation dates. From the ORE user guide: Stress Scenario definition, see section the guide The parameter stressConfigFile of the xvaExplain analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 74, false, null),
        ('xvaSensitivity.marketConfigFile', 'xvaSensitivity', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 0, 5, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The xvaSensitivity analytic computes bump and revalue sensitivities of the value adjustments. The parameter marketConfigFile of the xvaSensitivity analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 75, false, null),
        ('xvaSensitivity.sensitivityConfigFile', 'xvaSensitivity', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 5, 5, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The xvaSensitivity analytic computes bump and revalue sensitivities of the value adjustments. The parameter sensitivityConfigFile of the xvaSensitivity analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 76, false, null),
        ('xvaStress.marketConfigFile', 'xvaStress', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 3, 7, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The xvaStress analytic computes the change of the value adjustments under user defined stress scenarios. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. Only a subset of the specification is needed (the one given under Market, see the guide for a detailed description). The parameter marketConfigFile of the xvaStress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 77, false, null),
        ('xvaStress.sensitivityConfigFile', 'xvaStress', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity_stress.xml', 3, 3, 'What it holds: A sensitivity configuration for the stressed runs. It lists the risk factors to bump in the stressed market and uses a shift size that suits the stress, so the stressed sensitivities are computed on the stressed market. The xvaStress analytic computes the change of the value adjustments under user defined stress scenarios. From the ORE user guide: Configuration file for the sensitivity calculation, see section the guide. The parameter sensitivityConfigFile of the xvaStress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 78, false, null),
        ('xvaStress.stressConfigFile', 'xvaStress', 'stressConfigFile', 'input', 'input_document', 'xml', 'stress.xsd', null, 'stresstest.xml', 7, 7, 'What it holds: Stress tests can be applied in ORE to the same market segments and with same granularity as described in the sensitivity section the guide. This file stressconfig.xml specifies how stress tests can be configured. The general structure is shown in listing the guide. In this example, two zero stress scenarios "parallel_rates" and "twist" and one par rate "par_parallel" are defined. Each scenario definition contains the market components to be shifted in this scenario in a similar syntax that is also used for the sensitivity configuration, see the guide. In addition to the "Absolute" and "Relative" shift types defined in sensitivity configuration, stress tests allow an "EqualTo" shift type. In this case, the user provides the values that the curve should be shifted to. In the case of Discount, Yield, Index curves, and Survival Probabilities, an additional field "ShiftingZeros" is required to indicate if the given shifted values are zero rates (true) or discount rates (false). The xvaStress analytic computes the change of the value adjustments under user defined stress scenarios. From the ORE user guide: Stress Scenario definition, see section the guide The parameter stressConfigFile of the xvaStress analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 79, false, null),
        ('zeroToParSensiConversion.marketConfigFile', 'zeroToParSensiConversion', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 3, 3, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The zeroToParSensiConversion analytic converts raw (zero rate) sensitivities into par sensitivities. From the ORE user guide: Configuration file defining the simulation market under which sensitivities are computed, see the guide. Only a subset of the specification is needed (the one given under Market, see the guide for a detailed description). The parameter marketConfigFile of the zeroToParSensiConversion analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 80, false, null),
        ('zeroToParSensiConversion.pricingEnginesFile', 'zeroToParSensiConversion', 'pricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine.xml', 3, 3, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The zeroToParSensiConversion analytic converts raw (zero rate) sensitivities into par sensitivities. From the ORE user guide: Configuration file for the pricing engines to be used for sensitivity calculation. The parameter pricingEnginesFile of the zeroToParSensiConversion analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 81, false, null),
        ('zeroToParSensiConversion.sensitivityConfigFile', 'zeroToParSensiConversion', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 3, 3, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The zeroToParSensiConversion analytic converts raw (zero rate) sensitivities into par sensitivities. From the ORE user guide: Configuration file for the sensitivity calculation, see section the guide. The parameter sensitivityConfigFile of the zeroToParSensiConversion analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 82, false, null),
        ('zeroToParShift.marketConfigFile', 'zeroToParShift', 'marketConfigFile', 'input', 'input_document', 'xml', 'simulation.xsd', null, 'simulation.xml', 2, 2, 'What it holds: This file determines the behaviour of the risk factor simulation (scenario generation) module. It is structured in three blocks of data. Grid: Specifies the simulation time grid, here 80 quarterly steps. is set to for instance 2W in a netting set definition in netting.xml, then one has to set Grid to for instance 80,2W. TimeStepsPerYear: Minimum number of time steps per year to be used to evolve the stochastic process. This is useful if Euler discretization with a coarse Grid is used. Optional, defaults to null which means only the points specified under Grid are used to evolve the stochastic process. Calendar: Calendar or combination of calendars used to adjust the dates of the grid. Date adjustment is required because the simulation must step over `good'' dates on which index fixings can be stored. DayCounter: Day count convention used to translate dates to times. Optional, defaults to ActualActual ISDA. item Sequence: Choose random sequence generator (MersenneTwister, MersenneTwisterAntithetic, Sobol, Burley2020Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge). Seed: Random number generator seed Samples: Number of Monte Carlo paths to be produced use (Backward, Forward, BestOfForwardBackward, InterpolatedForwardBackward), which number of forward horizon days to use if one of the Forward related methods is chosen. Ordering: If the sequence type SobolBrownianBridge or The zeroToParShift analytic converts the raw market moves of a stress scenario into the equivalent par moves. The parameter marketConfigFile of the zeroToParShift analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 83, false, null),
        ('zeroToParShift.pricingEnginesFile', 'zeroToParShift', 'pricingEnginesFile', 'input', 'input_document', 'xml', 'pricingengines.xsd', null, 'pricingengine.xml', 2, 2, 'What it holds: The pricing engines. It maps each product type to the model and the engine that prices it, with the model and engine parameters, for example the analytic or Monte Carlo engine of a swaption and its tolerances. A trade whose product has no entry cannot be priced, and a different entry changes its value. The zeroToParShift analytic converts the raw market moves of a stress scenario into the equivalent par moves. The parameter pricingEnginesFile of the zeroToParShift analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 84, false, null),
        ('zeroToParShift.sensitivityConfigFile', 'zeroToParShift', 'sensitivityConfigFile', 'input', 'input_document', 'xml', 'sensitivity.xsd', null, 'sensitivity.xml', 2, 2, 'What it holds: ORE currently supports sensitivity analysis with respect to Discount curves (in the zero rate domain) Index curves (in the zero rate domain) Yield curves including e.g. equity forecast yield curves (in the zero rate domain) FX Spots FX volatilities Swaption volatilities, ATM matrix or cube Cap/Floor volatility matrices (in the caplet/floorlet domain) Default probability curves (in the "zero rate" domain, expressing survival probabilities S(t) in term of zero rates z(t) via S(t)=(-z(t) t) with Actual/365 day counter) Equity spot prices Equity volatilities, ATM or including strike dimension Zero inflation curves Year-on-Year inflation curves CDS volatilities Bond credit spreads Base correlation curves Correlation termstructures Commodity curves Intraday power curves The sensitivity.xml file specifies how sensitivities are computed for each market component. The general structure is shown in listing the guide, for a more comprehensive case see Examples/Example_15. A subset of the following parameters is used in each market component to specify the sensitivity analysis: ShiftType: Both absolute or relative shifts can be used to compute a sensitivity, specified by the key words Absolute resp. Relative. ShiftSize: The size of the shift to apply. ShiftScheme: The finite difference scheme to use (Forward, Backward, Central), if not given, this parameter defaults to Forward The zeroToParShift analytic converts the raw market moves of a stress scenario into the equivalent par moves. From the ORE user guide: Sensitivity parameterisation for the sensitivity analysis on asofDate The parameter sensitivityConfigFile of the zeroToParShift analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 85, false, null),
        ('zeroToParShift.stressConfigFile', 'zeroToParShift', 'stressConfigFile', 'input', 'input_document', 'xml', 'stress.xsd', null, 'stresstest.xml', 2, 2, 'What it holds: Stress tests can be applied in ORE to the same market segments and with same granularity as described in the sensitivity section the guide. This file stressconfig.xml specifies how stress tests can be configured. The general structure is shown in listing the guide. In this example, two zero stress scenarios "parallel_rates" and "twist" and one par rate "par_parallel" are defined. Each scenario definition contains the market components to be shifted in this scenario in a similar syntax that is also used for the sensitivity configuration, see the guide. In addition to the "Absolute" and "Relative" shift types defined in sensitivity configuration, stress tests allow an "EqualTo" shift type. In this case, the user provides the values that the curve should be shifted to. In the case of Discount, Yield, Index curves, and Survival Probabilities, an additional field "ShiftingZeros" is required to indicate if the given shifted values are zero rates (true) or discount rates (false). The zeroToParShift analytic converts the raw market moves of a stress scenario into the equivalent par moves. The parameter stressConfigFile of the zeroToParShift analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 86, false, null),
        ('imschedule.crif', 'imschedule', 'crif', 'input', 'data_file', 'csv', null, null, 'crif_schedule.csv', 2, 2, 'What it holds: The CRIF for the IM Schedule method. The imschedule analytic computes the basic initial margin from minimal trade information. The file has two lines for each trade, one with the risk class PV, whose amount is the NPV, and one with the risk class Notional, whose amount is the notional. It also needs the product class and the end date of each trade. The imschedule analytic computes the initial margin with the IM Schedule method, from minimal trade information in a CRIF. From the ORE user guide: CRIF file name. If the crif.csv input is omitted, then the ORE crif analytic (see below) is used internally to generate the CRIF input. However, CRIF generation in ORE is limited to IR/FX risks, whereas the SIMM analytic can process a full CRIF across IR/FX/INF/EQ/CR/COM risks. The parameter crif of the imschedule analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 87, false, null),
        ('pnl.portfolioMporFile', 'pnl', 'portfolioMporFile', 'input', 'data_file', 'xml', 'input.xsd', null, 'mporportfolio.xml', 3, 3, 'What it holds: The portfolio as it stands after the margin period of risk. It holds the trades valued at the later date, so the profit and loss over that period can be computed from the two portfolios. The pnl analytic computes a single period profit and loss between the as-of date and a later date. The parameter portfolioMporFile of the pnl analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 88, false, null),
        ('pnlExplain.portfolioMporFile', 'pnlExplain', 'portfolioMporFile', 'input', 'data_file', 'xml', 'input.xsd', null, 'mporportfolio.xml', 5, 5, 'What it holds: The portfolio as it stands after the margin period of risk. It holds the trades valued at the later date, so the profit and loss over that period can be computed from the two portfolios. The pnlExplain analytic explains that profit and loss in terms of raw or par sensitivities. The parameter portfolioMporFile of the pnlExplain analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 89, false, null),
        ('sacva.cvaSensitivitiesFile', 'sacva', 'cvaSensitivitiesFile', 'input', 'data_file', 'csv', null, null, 'xva_par_sensitivity_cva.csv', 3, 3, 'What it holds: The par sensitivities of the credit valuation adjustment. The sacva analytic computes the SA-CVA capital charge from CVA sensitivities. These can be computed on the fly, by running the xvaSensitivity analytic first, or they can be provided externally, and this file is the external form. The sacva analytic computes the SA-CVA capital from CVA sensitivities, computed on the fly or provided. The parameter cvaSensitivitiesFile of the sacva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 90, false, null),
        ('correlation.historicalScenarioFile', 'correlation', 'historicalScenarioFile', 'input', 'data_file', 'csv', null, null, 'scenarios.csv', 1, 1, 'What it holds: The historical scenarios. Each row is the move of a risk factor between two dates. The historical simulation takes its scenarios from here. The correlation analytic estimates the correlation of the risk factors from historical scenarios. From the ORE user guide: csv file containing the market scenarios for each date in the observation periods defined below; the granularity of the scenarios (e.g. discount and index curves, number of yield curve tenors) needs to match the simulation market definition above; each yield curve tenor scenario is represented as a discount factor. The parameter historicalScenarioFile of the correlation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 92, false, null),
        ('historicalSimulationVar.historicalScenarioFile', 'historicalSimulationVar', 'historicalScenarioFile', 'input', 'data_file', 'csv', null, null, 'scenarios.csv', 4, 5, 'What it holds: The historical scenarios. Each row is the move of a risk factor between two dates. The historical simulation takes its scenarios from here. The historicalSimulationVar analytic computes value at risk from historical scenarios. From the ORE user guide: csv file containing the market scenarios for each date in the observation periods; the granularity of the scenarios must match the simulation market definition. The parameter historicalScenarioFile of the historicalSimulationVar analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 93, false, null),
        ('parametricVar.covarianceInputFile', 'parametricVar', 'covarianceInputFile', 'input', 'data_file', 'csv', null, null, 'covariance.csv', 3, 3, 'What it holds: The covariance data for the parametric value at risk. ORE does not calculate covariances, so the file is provided from outside. It is a blank, tab or comma separated file with three columns: the two risk factors and their covariance. The parametricVar analytic computes value at risk from sensitivities and a covariance matrix. The parameter covarianceInputFile of the parametricVar analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 95, false, null),
        ('simulation.scenarioFile', 'simulation', 'scenarioFile', 'input', 'data_file', 'csv', null, null, 'scenarios.csv', 1, 1, 'What it holds: The historical scenarios. Each row is the move of a risk factor between two dates. The historical simulation takes its scenarios from here. The simulation analytic simulates the risk factors and values the portfolio on every path. The parameter scenarioFile of the simulation analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 100, false, null),
        ('xva.deterministicInitialMarginFile', 'xva', 'deterministicInitialMarginFile', 'input', 'data_file', 'csv', null, null, 'dim_evolution.csv', 1, 1, 'What it holds: The evolution of the dynamic initial margin: a deterministic initial margin for each date, read by the xva analytic when it is given the initial margin as a file. The xva analytic computes the exposure profiles and the valuation adjustments. The parameter deterministicInitialMarginFile of the xva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 105, false, null),
        ('xva.historicalScenarioFile', 'xva', 'historicalScenarioFile', 'input', 'data_file', 'csv', null, null, 'scenarios.csv', 1, 1, 'What it holds: The historical scenarios. Each row is the move of a risk factor between two dates. The historical simulation takes its scenarios from here. The xva analytic computes the exposure profiles and the valuation adjustments. The parameter historicalScenarioFile of the xva analytic names it. ORE Studio reads the file when it imports a run, and cannot yet parse it into entities.', 106, false, null),
        ('additionalResults.outputFileName', 'additionalResults', 'outputFileName', 'output', 'output_file', 'csv', null, null, 'additional_results.csv', 5, 7, 'What it holds: The additional results report. It holds the extra figures that the pricing engines produce for a trade besides its value, such as model specific outputs. The additionalResults analytic writes a report of the additional results that the pricing engines produce, which are engine specific. A run names it with the parameter outputFileName of the additionalResults analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 110, true, null),
        ('calibration.meanReversionOutputFileName', 'calibration', 'meanReversionOutputFileName', 'output', 'output_file', 'csv', null, null, 'meanReversion.csv', 2, 2, 'What it holds: The mean reversion report of a calibration. It gives the mean reversion values that the calibration found for the model, so they can be compared between runs. The calibration analytic calibrates the simulation model to the market. From the ORE user guide: The output file name for kappa and v for each curve. A run names it with the parameter meanReversionOutputFileName of the calibration analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 111, false, null),
        ('calibration.outputFile', 'calibration', 'outputFile', 'output', 'output_file', 'csv', null, null, 'calibration.csv', 12, 12, 'What it holds: The calibration report. It gives the calibrated model parameters, for example the volatility and mean reversion of each currency, with the calibration instruments and the fit error. The calibration analytic calibrates the simulation model to the market. A run names it with the parameter outputFile of the calibration analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 112, true, null),
        ('calibration.outputFileName', 'calibration', 'outputFileName', 'output', 'output_file', 'csv', null, null, 'calibration.csv', 0, 0, 'What it holds: The calibration report. It gives the calibrated model parameters, for example the volatility and mean reversion of each currency, with the calibration instruments and the fit error. The calibration analytic calibrates the simulation model to the market. A run names it with the parameter outputFileName of the calibration analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 113, false, null),
        ('calibration.pcaOutputFileName', 'calibration', 'pcaOutputFileName', 'output', 'output_file', 'csv', null, null, 'pca.csv', 1, 1, 'What it holds: The principal component report. It gives the eigenvectors and eigenvalues of the curve moves, from which the model volatility structure is derived. The calibration analytic calibrates the simulation model to the market. From the ORE user guide: The output file name of eigenvalues and eigenvectors retained for each currency. A run names it with the parameter pcaOutputFileName of the calibration analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 114, false, null),
        ('cashflow.outputFileName', 'cashflow', 'outputFileName', 'output', 'output_file', 'csv', null, null, 'flows.csv', 314, 336, 'What it holds: The cash flow report. One row for each future cash flow of each trade with the pay date, amount, currency, the legs and the flow type, with the discounted present value. It shows how the NPV is made up. The cashflow analytic lists the future cash flows of every trade. A run names it with the parameter outputFileName of the cashflow analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 115, true, null),
        ('correlation.outputFile', 'correlation', 'outputFile', 'output', 'output_file', 'csv', null, null, 'correlation.csv', 1, 1, 'What it holds: The correlation matrix of the risk factors. The XVA analytic reads it to correlate the simulated factors, and the correlation analytic writes it from the historical scenarios. The correlation analytic estimates the correlation of the risk factors from historical scenarios. From the ORE user guide: Output file name A run names it with the parameter outputFile of the correlation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 116, true, null),
        ('creditcurves.outputFileName', 'creditcurves', 'outputFileName', 'output', 'output_file', 'csv', null, null, 'creditcurves.csv', 15, 15, 'What it holds: The credit curve report. It lists the survival probabilities of the credit curves on a grid of dates, so the default curves the run built can be checked. The creditcurves analytic reports the credit curves the run built. A run names it with the parameter outputFileName of the creditcurves analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 117, true, null),
        ('crif.crifOutputFile', 'crif', 'crifOutputFile', 'output', 'output_file', 'csv', null, null, 'crif.csv', 2, 2, 'What it holds: The CRIF, the sensitivities in the Common Risk Interchange Format defined by ISDA. The crif analytic generates it from a par sensitivity analysis with a SIMM specific sensitivity configuration, after labelling the sensitivities so the file meets the CRIF format. The simm analytic reads it to compute the initial margin. ORE''s own CRIF generation covers interest rate and FX risks only, while the SIMM analytic can process a full CRIF across interest rate, FX, inflation, equity, credit and commodity risks. The crif analytic generates the CRIF, the input of the ISDA SIMM calculation, from a par sensitivity analysis. A run names it with the parameter crifOutputFile of the crif analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 118, true, null),
        ('curves.outputFileName', 'curves', 'outputFileName', 'output', 'output_file', 'csv', null, null, 'curves.csv', 315, 331, 'What it holds: The curve report. It lists the discount factors of the requested curves on a grid of dates, so the curves the run built can be checked against the market. The curves analytic reports the curves the run built. A run names it with the parameter outputFileName of the curves analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 119, true, null),
        ('historicalSimulationVar.outputFile', 'historicalSimulationVar', 'outputFile', 'output', 'output_file', 'csv', null, null, 'var.csv', 5, 5, 'What it holds: The value at risk report. It gives the value at risk of the portfolio and its breakdown by risk class, portfolio and trade at the requested quantiles. The historicalSimulationVar analytic computes value at risk from historical scenarios. From the ORE user guide: Output file name A run names it with the parameter outputFile of the historicalSimulationVar analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 120, true, null),
        ('npv.outputFileName', 'npv', 'outputFileName', 'output', 'output_file', 'csv', null, null, 'npv.csv', 333, 368, 'What it holds: The NPV report. One row for each trade with its id, type, maturity, net present value in the trade and base currencies, the notional and the netting set. It is the basic valuation result that most other reports are checked against. The npv analytic values every trade in the portfolio. A run names it with the parameter outputFileName of the npv analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 121, true, null),
        ('parStressConversion.scenarioOutputFile', 'parStressConversion', 'scenarioOutputFile', 'output', 'output_file', 'csv', null, null, 'stresstest.csv', 1, 1, 'What it holds: The stress test report. For each trade or netting set and each scenario it gives the base value, the stressed value and the change between them. The parStressConversion analytic converts a stress given on par rates into a stress on zero rates. From the ORE user guide: File containing the results of the sensitivity calculation in terms of the base scenario NPV, the scenario NPV and their difference. A run names it with the parameter scenarioOutputFile of the parStressConversion analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 122, true, null),
        ('parametricVar.outputFile', 'parametricVar', 'outputFile', 'output', 'output_file', 'csv', null, null, 'var.csv', 3, 3, 'What it holds: The value at risk report. It gives the value at risk of the portfolio and its breakdown by risk class, portfolio and trade at the requested quantiles. The parametricVar analytic computes value at risk from sensitivities and a covariance matrix. From the ORE user guide: Output file name A run names it with the parameter outputFile of the parametricVar analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 123, true, null),
        ('pfe.netCubeOutputFile', 'pfe', 'netCubeOutputFile', 'output', 'output_file', 'csv', null, null, 'netcube.csv', 1, 1, 'What it holds: The netted cube. It holds the exposure of each netting set on every date and sample, after the netting and the collateral. The exposure and XVA figures are taken from it. The pfe analytic computes the potential future exposure profiles. From the ORE user guide: File name for the aggregated NPV cube in human readable csv file format (per netting set, date, sample) after taking collateral into account. Leave empty to skip generation of this file. A run names it with the parameter netCubeOutputFile of the pfe analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 124, true, null),
        ('pfe.rawCubeOutputFile', 'pfe', 'rawCubeOutputFile', 'output', 'output_file', 'csv', null, null, 'rawcube.csv', 1, 1, 'What it holds: The raw cube. It holds the value of each trade on every date and sample before the netting and the collateral, so the netting set exposures can be rebuilt. The pfe analytic computes the potential future exposure profiles. From the ORE user guide: File name for the trade NPV cube in human readable csv file format (per trade, date, sample), leave empty to skip generation of this file. A run names it with the parameter rawCubeOutputFile of the pfe analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 125, true, null),
        ('pnl.outputFileName', 'pnl', 'outputFileName', 'output', 'output_file', 'csv', null, null, 'pnl.csv', 3, 3, 'What it holds: The profit and loss report. For each trade it gives the value at the as-of date, the value after the margin period of risk and the change between them. The pnl analytic computes a single period profit and loss between the as-of date and a later date. A run names it with the parameter outputFileName of the pnl analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 126, true, null),
        ('pnlExplain.outputFileName', 'pnlExplain', 'outputFileName', 'output', 'output_file', 'csv', null, null, 'pnl_explain.csv', 5, 5, 'What it holds: The profit and loss explain report. It splits the change in value over the margin period of risk into the parts caused by the movement of each risk factor and the unexplained rest. The pnlExplain analytic explains that profit and loss in terms of raw or par sensitivities. A run names it with the parameter outputFileName of the pnlExplain analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 127, true, null),
        ('portfolioDetails.marketObjectFileName', 'portfolioDetails', 'marketObjectFileName', 'output', 'output_file', 'csv', null, null, 'marketObjects.csv', 4, 4, 'What it holds: The market objects of the portfolio, written by the portfolioDetails analytic: the curves, surfaces and other market objects that the trades of the portfolio need for their valuation. The guide does not describe the columns. The portfolioDetails analytic describes the portfolio and what its valuation depends on. A run names it with the parameter marketObjectFileName of the portfolioDetails analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 128, true, null),
        ('portfolioDetails.riskFactorFileName', 'portfolioDetails', 'riskFactorFileName', 'output', 'output_file', 'csv', null, null, 'riskFactors.csv', 4, 4, 'What it holds: The risk factors of the portfolio, written by the portfolioDetails analytic: the risk factors that the trades of the portfolio depend on. The guide does not describe the columns. The portfolioDetails analytic describes the portfolio and what its valuation depends on. A run names it with the parameter riskFactorFileName of the portfolioDetails analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 129, true, null),
        ('sacva.saCvaNetSensitivitiesFile', 'sacva', 'saCvaNetSensitivitiesFile', 'output', 'output_file', 'csv', null, null, 'sacva_sensitivity.csv', 3, 3, 'What it holds: The net CVA sensitivities of the sacva analytic, the figures its SA-CVA capital calculation works on. The guide does not describe the columns. The sacva analytic computes the SA-CVA capital from CVA sensitivities, computed on the fly or provided. A run names it with the parameter saCvaNetSensitivitiesFile of the sacva analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 130, true, null),
        ('scenario.scenarioOutputFile', 'scenario', 'scenarioOutputFile', 'output', 'output_file', 'csv', null, null, 'scenario.csv', 3, 3, 'What it holds: A scenario file in the ORE csv format. The scenario analytic writes the base scenario of the simulation market to it. The sensitivity analytic writes the base scenario and the shifted scenarios to it. Other analytics read the file as the historical discount factors and FX spot rates they work from. The scenario analytic exports the base scenario of the simulation market as a file. A run names it with the parameter scenarioOutputFile of the scenario analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 131, true, null),
        ('scenarioGeneration.amcPathDataOutput', 'scenarioGeneration', 'amcPathDataOutput', 'output', 'output_file', 'dat', null, null, 'amcBuffer.dat', 2, 2, 'What it holds: The path data of an American Monte Carlo run, in binary form. The guide lists the parameter but does not describe the file. The scenarioGeneration analytic generates market scenarios, for example stress scenarios. A run names it with the parameter amcPathDataOutput of the scenarioGeneration analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 132, true, null),
        ('scenarioGeneration.scenarioOutputFile', 'scenarioGeneration', 'scenarioOutputFile', 'output', 'output_file', 'csv', null, null, 'stress_scenarios.csv', 1, 3, 'What it holds: The stress scenarios that the scenarioGeneration analytic writes, one row for each scenario and risk factor, so that the stress analytic can read them. The scenarioGeneration analytic generates market scenarios, for example stress scenarios. A run names it with the parameter scenarioOutputFile of the scenarioGeneration analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 133, true, null),
        ('scenarioGeneration.scenariodump', 'scenarioGeneration', 'scenariodump', 'output', 'output_file', 'csv', null, null, 'scenariodump.csv', 0, 0, 'What it holds: The full raw market scenarios that the simulation market generates, for example the discount factors of the yield curves on every date and sample, written for later inspection or reuse. ORE writes the file only when the parameter is given. The scenarioGeneration analytic generates market scenarios, for example stress scenarios. From the ORE user guide: File containing all the scenarios generated through simulation market. If the node is not given, this file will not be outputted. A run names it with the parameter scenariodump of the scenarioGeneration analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 134, false, null),
        ('sensitivity.crossGammaOutputFile', 'sensitivity', 'crossGammaOutputFile', 'output', 'output_file', 'csv', null, null, 'crossgamma.csv', 22, 31, 'What it holds: The cross gamma report. For pairs of risk factors it gives the second order change in value when both are bumped, the term a first order sensitivity misses. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. A run names it with the parameter crossGammaOutputFile of the sensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 135, false, null),
        ('sensitivity.jacobiInverseOutputFile', 'sensitivity', 'jacobiInverseOutputFile', 'output', 'output_file', 'csv', null, null, 'jacobi_inverse.csv', 26, 26, 'What it holds: The inverse Jacobian. The matrix that converts a shift of par rates back into the shift of zero rates. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. From the ORE user guide: Output file name for the inverse Jacobi matrix A run names it with the parameter jacobiInverseOutputFile of the sensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 136, false, null),
        ('sensitivity.jacobiOutputFile', 'sensitivity', 'jacobiOutputFile', 'output', 'output_file', 'csv', null, null, 'jacobi.csv', 26, 26, 'What it holds: The Jacobian. The matrix that converts a shift of zero rates into the shift of par rates, used to turn zero rate sensitivities into par rate sensitivities. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. From the ORE user guide: Output file name for the Jacobi matrix A run names it with the parameter jacobiOutputFile of the sensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 137, false, null),
        ('sensitivity.parRateSensitivityOutputFile', 'sensitivity', 'parRateSensitivityOutputFile', 'output', 'output_file', 'csv', null, null, 'parsensi.csv', 16, 16, 'What it holds: The par rate sensitivity report. It gives the sensitivities of the portfolio to par instrument quotes instead of zero rates. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. A run names it with the parameter parRateSensitivityOutputFile of the sensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 138, false, null),
        ('sensitivity.parSensitivityOutputFile', 'sensitivity', 'parSensitivityOutputFile', 'output', 'output_file', 'csv', null, null, 'parsensitivity.csv', 17, 26, 'What it holds: The par sensitivity report. It gives the sensitivities to par rates, such as swap rates, that the zero rate sensitivities convert to through the Jacobian. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. From the ORE user guide: Output file name for the par sensitivity report A run names it with the parameter parSensitivityOutputFile of the sensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 139, false, null),
        ('sensitivity.productClassMappingOutputFile', 'sensitivity', 'productClassMappingOutputFile', 'output', 'output_file', 'csv', null, null, 'productclass_mapping.csv', 2, 2, 'What it holds: The product class mapping that the sensitivity analytic can write. It maps the trades to the product classes of the sensitivity report. The guide does not describe the columns. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. A run names it with the parameter productClassMappingOutputFile of the sensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 140, false, null),
        ('sensitivity.scenarioOutputFile', 'sensitivity', 'scenarioOutputFile', 'output', 'output_file', 'csv', null, null, 'scenario.csv', 54, 73, 'What it holds: A scenario file in the ORE csv format. The scenario analytic writes the base scenario of the simulation market to it. The sensitivity analytic writes the base scenario and the shifted scenarios to it. Other analytics read the file as the historical discount factors and FX spot rates they work from. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. From the ORE user guide: File containing the results of the sensitivity calculation in terms of the base scenario NPV, the scenario NPV and their difference. A run names it with the parameter scenarioOutputFile of the sensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 141, true, null),
        ('sensitivity.sensitivityOutputFile', 'sensitivity', 'sensitivityOutputFile', 'output', 'output_file', 'csv', null, null, 'sensitivity.csv', 57, 70, 'What it holds: The sensitivity report. For each trade and risk factor it gives the base value, the shift, the shifted value and the sensitivity, which is the change in value for the bump. It is the input of the value at risk and the margin analytics. The sensitivity analytic bumps the risk factors and reports the sensitivities of the portfolio. From the ORE user guide: File containing the results of the sensitivity calculation in terms of the base scenario NPV, the shift size together with the risk-factor and the resulting first and (pure) second order finite differences. Also included is a second set of shift sizes together with the risk-factor with a (mixed) second order finite difference associated to a cross gamma calculation A run names it with the parameter sensitivityOutputFile of the sensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 142, true, null),
        ('simulation.additionalScenarioDataFileName', 'simulation', 'additionalScenarioDataFileName', 'output', 'output_file', 'dat', null, null, 'scenariodata.dat', 13, 13, 'What it holds: The scenario data of a simulation in binary form. It holds the simulated market factors for every date and sample. The simulation analytic simulates the risk factors and values the portfolio on every path. A run names it with the parameter additionalScenarioDataFileName of the simulation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 143, false, null),
        ('simulation.aggregationScenarioDataDump', 'simulation', 'aggregationScenarioDataDump', 'output', 'output_file', 'csv', null, null, 'scenariodata.csv', 30, 30, 'What it holds: The aggregation scenario data in plain text, the uncompressed form of the aggregation scenario data that the simulation writes. It holds the simulated FX rates and index fixings that the XVA post processor needs for the variation margin. The simulation analytic simulates the risk factors and values the portfolio on every path. A run names it with the parameter aggregationScenarioDataDump of the simulation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 144, false, null),
        ('simulation.aggregationScenarioDataFileName', 'simulation', 'aggregationScenarioDataFileName', 'output', 'output_file', 'csv_gz', null, null, 'scenariodata.csv.gz', 196, 229, 'What it holds: The aggregation scenario data written by a simulation. For every date and sample of the time grid it gives the simulated values of the market factors, compressed. The XVA post processing reads it to aggregate the exposures consistently with the paths. The simulation analytic simulates the risk factors and values the portfolio on every path. A run names it with the parameter aggregationScenarioDataFileName of the simulation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 145, true, null),
        ('simulation.amcPathDataOutput', 'simulation', 'amcPathDataOutput', 'output', 'output_file', 'dat', null, null, 'amcBuffer.dat', 1, 1, 'What it holds: The path data of an American Monte Carlo run, in binary form. The guide lists the parameter but does not describe the file. The simulation analytic simulates the risk factors and values the portfolio on every path. A run names it with the parameter amcPathDataOutput of the simulation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 146, false, null),
        ('simulation.cptyCubeFile', 'simulation', 'cptyCubeFile', 'output', 'output_file', 'csv_gz', null, null, 'cptyCube.csv.gz', 0, 0, 'What it holds: The NPV cube aggregated by counterparty, compressed. The simulation writes it together with the survival probabilities and the credit state NPVs, which the dynamic credit XVA calculation needs. The simulation analytic simulates the risk factors and values the portfolio on every path. A run names it with the parameter cptyCubeFile of the simulation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 147, false, null),
        ('simulation.cubeFile', 'simulation', 'cubeFile', 'output', 'output_file', 'csv_gz', null, null, 'cube.csv.gz', 196, 241, 'What it holds: The valuation cube of a simulation, compressed. It holds the simulated value of each trade for every date and sample of the time grid. The XVA and exposure analytics read it to compute the exposure profiles. The simulation analytic simulates the risk factors and values the portfolio on every path. A run names it with the parameter cubeFile of the simulation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 148, true, null),
        ('simulation.nettingSetCubeFile', 'simulation', 'nettingSetCubeFile', 'output', 'output_file', 'csv_gz', null, null, 'nettingSetCube.csv.gz', 0, 0, 'What it holds: The NPV cube aggregated by netting set, compressed, with the NPVs converted into the base currency of the simulation. The simulation writes it next to the trade level cube, so the post processing can start from netting set values without aggregating the trades again. The simulation analytic simulates the risk factors and values the portfolio on every path. A run names it with the parameter nettingSetCubeFile of the simulation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 149, false, null),
        ('simulation.scenariodump', 'simulation', 'scenariodump', 'output', 'output_file', 'csv', null, null, 'scenariodump.csv', 47, 48, 'What it holds: The full raw market scenarios that the simulation market generates, for example the discount factors of the yield curves on every date and sample, written for later inspection or reuse. ORE writes the file only when the parameter is given. The simulation analytic simulates the risk factors and values the portfolio on every path. A run names it with the parameter scenariodump of the simulation analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 150, false, null),
        ('stress.scenarioCashflowOutputFile', 'stress', 'scenarioCashflowOutputFile', 'output', 'output_file', 'csv', null, null, 'stresstest_flows.csv', 5, 5, 'What it holds: The stress test cash flow report. It lists the cash flows of each trade under each stress scenario, so the stressed values can be traced to their flows. The stress analytic revalues the portfolio under stress scenarios. A run names it with the parameter scenarioCashflowOutputFile of the stress analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 151, false, null),
        ('stress.scenarioOutputFile', 'stress', 'scenarioOutputFile', 'output', 'output_file', 'csv', null, null, 'stresstest.csv', 14, 17, 'What it holds: The stress test report. For each trade or netting set and each scenario it gives the base value, the stressed value and the change between them. The stress analytic revalues the portfolio under stress scenarios. From the ORE user guide: File containing the results of the sensitivity calculation in terms of the base scenario NPV, the scenario NPV and their difference. A run names it with the parameter scenarioOutputFile of the stress analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 152, true, null),
        ('xva.dimEvolutionFile', 'xva', 'dimEvolutionFile', 'output', 'output_file', 'txt', null, null, 'dim_evolution.txt', 1, 93, 'What it holds: The evolution of the dynamic initial margin. The xva analytic writes the evolution of the zero order DIM and the average of the nth order DIM through time. The xva analytic computes the exposure profiles and the valuation adjustments. From the ORE user guide: Output file name to store the evolution of zero order DIM and average of nth order DIM through time A run names it with the parameter dimEvolutionFile of the xva analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 153, false, null),
        ('xva.dimRegressionFiles', 'xva', 'dimRegressionFiles', 'output', 'output_file', 'txt', null, null, 'dim_regression.txt', 9, 87, 'What it holds: A snapshot of the regression that the dynamic initial margin model fits. The xva analytic writes it, and a list of file names can be given when more than one snapshot is needed. The xva analytic computes the exposure profiles and the valuation adjustments. From the ORE user guide: Output file name(s) for a DIM regression snapshot, comma separated list A run names it with the parameter dimRegressionFiles of the xva analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 154, false, null),
        ('xva.netCubeOutputFile', 'xva', 'netCubeOutputFile', 'output', 'output_file', 'csv', null, null, 'netcube.csv', 230, 230, 'What it holds: The netted cube. It holds the exposure of each netting set on every date and sample, after the netting and the collateral. The exposure and XVA figures are taken from it. The xva analytic computes the exposure profiles and the valuation adjustments. From the ORE user guide: File name for the aggregated NPV cube in human readable csv file format (per netting set, date, sample) after taking collateral into account. Leave empty to skip generation of this file. A run names it with the parameter netCubeOutputFile of the xva analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 155, true, null),
        ('xva.rawCubeOutputFile', 'xva', 'rawCubeOutputFile', 'output', 'output_file', 'csv', null, null, 'rawcube.csv', 229, 229, 'What it holds: The raw cube. It holds the value of each trade on every date and sample before the netting and the collateral, so the netting set exposures can be rebuilt. The xva analytic computes the exposure profiles and the valuation adjustments. From the ORE user guide: File name for the trade NPV cube in human readable csv file format (per trade, date, sample), leave empty to skip generation of this file. A run names it with the parameter rawCubeOutputFile of the xva analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 156, true, null),
        ('xva.timeAveragedNettedExposureOutputFile', 'xva', 'timeAveragedNettedExposureOutputFile', 'output', 'output_file', 'csv', null, null, 'timeaveragedexposure.csv', 1, 1, 'What it holds: The time averaged netted exposure that the xva analytic writes, one figure for each netting set. The guide does not describe the columns. The xva analytic computes the exposure profiles and the valuation adjustments. A run names it with the parameter timeAveragedNettedExposureOutputFile of the xva analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 157, false, null),
        ('xvaSensitivity.jacobiInverseOutputFile', 'xvaSensitivity', 'jacobiInverseOutputFile', 'output', 'output_file', 'csv', null, null, 'xva_sensitivity_jacobi_inverse.csv', 5, 5, 'What it holds: The inverse of the XVA sensitivity Jacobian, used to convert par rate sensitivities back to zero rate sensitivities. The xvaSensitivity analytic computes bump and revalue sensitivities of the value adjustments. A run names it with the parameter jacobiInverseOutputFile of the xvaSensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 158, true, null),
        ('xvaSensitivity.jacobiOutputFile', 'xvaSensitivity', 'jacobiOutputFile', 'output', 'output_file', 'csv', null, null, 'xva_sensitivity_jacobi.csv', 5, 5, 'What it holds: The Jacobian of the XVA sensitivity run: the matrix that turns sensitivities to zero rates into sensitivities to par rates. The xvaSensitivity analytic computes bump and revalue sensitivities of the value adjustments. A run names it with the parameter jacobiOutputFile of the xvaSensitivity analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 159, true, null),
        ('zeroToParSensiConversion.jacobiInverseOutputFile', 'zeroToParSensiConversion', 'jacobiInverseOutputFile', 'output', 'output_file', 'csv', null, null, 'jacobi_inverse.csv', 3, 3, 'What it holds: The inverse Jacobian. The matrix that converts a shift of par rates back into the shift of zero rates. The zeroToParSensiConversion analytic converts raw (zero rate) sensitivities into par sensitivities. From the ORE user guide: Output file name for the inverse Jacobi matrix A run names it with the parameter jacobiInverseOutputFile of the zeroToParSensiConversion analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 160, true, null),
        ('zeroToParSensiConversion.jacobiOutputFile', 'zeroToParSensiConversion', 'jacobiOutputFile', 'output', 'output_file', 'csv', null, null, 'jacobi.csv', 3, 3, 'What it holds: The Jacobian. The matrix that converts a shift of zero rates into the shift of par rates, used to turn zero rate sensitivities into par rate sensitivities. The zeroToParSensiConversion analytic converts raw (zero rate) sensitivities into par sensitivities. From the ORE user guide: Output file name for the Jacobi matrix A run names it with the parameter jacobiOutputFile of the zeroToParSensiConversion analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 161, true, null),
        ('zeroToParSensiConversion.outputFile', 'zeroToParSensiConversion', 'outputFile', 'output', 'output_file', 'csv', null, null, 'parconversion_sensitivity.csv', 3, 3, 'What it holds: The converted sensitivities. It gives the sensitivities to par rates that the conversion computed from the zero rate sensitivities. The zeroToParSensiConversion analytic converts raw (zero rate) sensitivities into par sensitivities. A run names it with the parameter outputFile of the zeroToParSensiConversion analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 162, true, null),
        ('zeroToParShift.parShiftsFile', 'zeroToParShift', 'parShiftsFile', 'output', 'output_file', 'csv', null, null, 'parshifts.csv', 2, 2, 'What it holds: The par shifts that the zeroToParShift analytic writes. ORE''s scenario machinery works in the raw (zero rate) domain, and the pnlExplain analytic, when it works on par sensitivities, needs the market moves between two dates as par rate shifts. This file holds the raw moves of a stress scenario converted into the equivalent par moves. The zeroToParShift analytic converts the raw market moves of a stress scenario into the equivalent par moves. A run names it with the parameter parShiftsFile of the zeroToParShift analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 163, true, null),
        ('zeroToParShift.scenarioOutputFile', 'zeroToParShift', 'scenarioOutputFile', 'output', 'output_file', 'csv', null, null, 'stresstest.csv', 2, 2, 'What it holds: The stress test report. For each trade or netting set and each scenario it gives the base value, the stressed value and the change between them. The zeroToParShift analytic converts the raw market moves of a stress scenario into the equivalent par moves. A run names it with the parameter scenarioOutputFile of the zeroToParShift analytic, so the result has one predictable name in the output folder. ORE Studio does not parse it.', 164, true, null),
        ('calibration.scenarioInputFile', 'calibration', 'scenarioInputFile', 'input', 'intermediate_file', 'csv', null, null, 'scenario.csv', 1, 1, 'What it holds: A scenario file in the ORE csv format. The scenario analytic writes the base scenario of the simulation market to it. The sensitivity analytic writes the base scenario and the shifted scenarios to it. Other analytics read the file as the historical discount factors and FX spot rates they work from. The calibration analytic calibrates the simulation model to the market. From the ORE user guide: The path to the file which contains the historical discount factors and historical FX spot rates. Must be in the scenario.csv ORE format. Only needed when pcaCalibration set to true. The parameter scenarioInputFile of the calibration analytic names it. The sensitivity analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 91, false, 'sensitivity.scenarioOutputFile'),
        ('historicalSimulationVar.sensitivityInputFile', 'historicalSimulationVar', 'sensitivityInputFile', 'input', 'intermediate_file', 'csv', null, null, 'sensitivity.csv', 1, 1, 'What it holds: The sensitivity report. For each trade and risk factor it gives the base value, the shift, the shifted value and the sensitivity, which is the change in value for the bump. It is the input of the value at risk and the margin analytics. The historicalSimulationVar analytic computes value at risk from historical scenarios. From the ORE user guide: Reference to the sensitivity (deltas, vegas, gammas) and cross gamma input as generated by ORE in a comma separated list The parameter sensitivityInputFile of the historicalSimulationVar analytic names it. The sensitivity analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 94, false, 'sensitivity.sensitivityOutputFile'),
        ('parametricVar.sensitivityInputFile', 'parametricVar', 'sensitivityInputFile', 'input', 'intermediate_file', 'csv', null, null, 'sensitivity.csv', 3, 3, 'What it holds: The sensitivity report. For each trade and risk factor it gives the base value, the shift, the shifted value and the sensitivity, which is the change in value for the bump. It is the input of the value at risk and the margin analytics. The parametricVar analytic computes value at risk from sensitivities and a covariance matrix. From the ORE user guide: Reference to the sensitivity (deltas, vegas, gammas) and cross gamma input as generated by ORE in a comma separated list The parameter sensitivityInputFile of the parametricVar analytic names it. The sensitivity analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 96, true, 'sensitivity.sensitivityOutputFile'),
        ('pfe.cubeFile', 'pfe', 'cubeFile', 'input', 'intermediate_file', 'csv_gz', null, null, 'cube.csv.gz', 0, 1, 'What it holds: The valuation cube of a simulation, compressed. It holds the simulated value of each trade for every date and sample of the time grid. The XVA and exposure analytics read it to compute the exposure profiles. The pfe analytic computes the potential future exposure profiles. From the ORE user guide: NPV cube file previously generated and to be post-processed here The parameter cubeFile of the pfe analytic names it. The simulation analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 97, true, 'simulation.cubeFile'),
        ('pfe.scenarioFile', 'pfe', 'scenarioFile', 'input', 'intermediate_file', 'csv_gz', null, null, 'scenariodata.csv.gz', 0, 1, 'What it holds: The aggregation scenario data written by a simulation. For every date and sample of the time grid it gives the simulated values of the market factors, compressed. The XVA post processing reads it to aggregate the exposures consistently with the paths. The pfe analytic computes the potential future exposure profiles. From the ORE user guide: Scenario data previously generated and used in the post-processor (simulated index fixings and FX rates) The parameter scenarioFile of the pfe analytic names it. The simulation analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 98, true, 'simulation.aggregationScenarioDataFileName'),
        ('simm.crif', 'simm', 'crif', 'input', 'intermediate_file', 'csv', null, null, 'crif.csv', 16, 16, 'What it holds: The CRIF, the sensitivities in the Common Risk Interchange Format defined by ISDA. The crif analytic generates it from a par sensitivity analysis with a SIMM specific sensitivity configuration, after labelling the sensitivities so the file meets the CRIF format. The simm analytic reads it to compute the initial margin. ORE''s own CRIF generation covers interest rate and FX risks only, while the SIMM analytic can process a full CRIF across interest rate, FX, inflation, equity, credit and commodity risks. The simm analytic computes initial margin with ISDA''s Standard Initial Margin Model from a CRIF. From the ORE user guide: CRIF file name. If the crif.csv input is omitted, then the ORE crif analytic (see below) is used internally to generate the CRIF input. However, CRIF generation in ORE is limited to IR/FX risks, whereas the SIMM analytic can process a full CRIF across IR/FX/INF/EQ/CR/COM risks. The parameter crif of the simm analytic names it. The crif analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 99, true, 'crif.crifOutputFile'),
        ('stress.scenarioFile', 'stress', 'scenarioFile', 'input', 'intermediate_file', 'csv', null, null, 'stress_scenarios.csv', 1, 1, 'What it holds: The stress scenarios that the scenarioGeneration analytic writes, one row for each scenario and risk factor, so that the stress analytic can read them. The stress analytic revalues the portfolio under stress scenarios. The parameter scenarioFile of the stress analytic names it. The scenarioGeneration analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 101, false, 'scenarioGeneration.scenarioOutputFile'),
        ('xva.correlationInputFile', 'xva', 'correlationInputFile', 'input', 'intermediate_file', 'csv', null, null, 'correlation.csv', 1, 1, 'What it holds: The correlation matrix of the risk factors. The XVA analytic reads it to correlate the simulated factors, and the correlation analytic writes it from the historical scenarios. The xva analytic computes the exposure profiles and the valuation adjustments. The parameter correlationInputFile of the xva analytic names it. The correlation analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 102, false, 'correlation.outputFile'),
        ('xva.cptyCubeFile', 'xva', 'cptyCubeFile', 'input', 'intermediate_file', 'csv_gz', null, null, 'cptyCube.csv.gz', 0, 0, 'What it holds: The NPV cube aggregated by counterparty, compressed. The simulation writes it together with the survival probabilities and the credit state NPVs, which the dynamic credit XVA calculation needs. The xva analytic computes the exposure profiles and the valuation adjustments. The parameter cptyCubeFile of the xva analytic names it. The simulation analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 103, false, 'simulation.cptyCubeFile'),
        ('xva.cubeFile', 'xva', 'cubeFile', 'input', 'intermediate_file', 'csv_gz', null, null, 'cube.csv.gz', 199, 243, 'What it holds: The valuation cube of a simulation, compressed. It holds the simulated value of each trade for every date and sample of the time grid. The XVA and exposure analytics read it to compute the exposure profiles. The xva analytic computes the exposure profiles and the valuation adjustments. From the ORE user guide: NPV cube file previously generated and to be post-processed here The parameter cubeFile of the xva analytic names it. The simulation analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 104, true, 'simulation.cubeFile'),
        ('xva.nettingSetCubeFile', 'xva', 'nettingSetCubeFile', 'input', 'intermediate_file', 'csv_gz', null, null, 'nettingSetCube.csv.gz', 0, 0, 'What it holds: The NPV cube aggregated by netting set, compressed, with the NPVs converted into the base currency of the simulation. The simulation writes it next to the trade level cube, so the post processing can start from netting set values without aggregating the trades again. The xva analytic computes the exposure profiles and the valuation adjustments. The parameter nettingSetCubeFile of the xva analytic names it. The simulation analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 107, false, 'simulation.nettingSetCubeFile'),
        ('xva.scenarioFile', 'xva', 'scenarioFile', 'input', 'intermediate_file', 'csv_gz', null, null, 'scenariodata.csv.gz', 198, 242, 'What it holds: The aggregation scenario data written by a simulation. For every date and sample of the time grid it gives the simulated values of the market factors, compressed. The XVA post processing reads it to aggregate the exposures consistently with the paths. The xva analytic computes the exposure profiles and the valuation adjustments. From the ORE user guide: Scenario data previously generated and used in the post-processor (simulated index fixings and FX rates) The parameter scenarioFile of the xva analytic names it. The simulation analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 108, true, 'simulation.aggregationScenarioDataFileName'),
        ('zeroToParSensiConversion.sensitivityInputFile', 'zeroToParSensiConversion', 'sensitivityInputFile', 'input', 'intermediate_file', 'csv', null, null, 'sensitivity.csv', 3, 3, 'What it holds: The sensitivity report. For each trade and risk factor it gives the base value, the shift, the shifted value and the sensitivity, which is the change in value for the bump. It is the input of the value at risk and the margin analytics. The zeroToParSensiConversion analytic converts raw (zero rate) sensitivities into par sensitivities. From the ORE user guide: The raw sensitivities are passed in (parameter sensitivityInputFile), all other parameters as above. There is one new parameter *sensitivityInputFile* which points to a csv file with the raw (zero)sensitivities. The raw sensitivities csv input file *sensitivityInputFile* needs to have at least six columns, the column names can be user configured in the master input file. The parameter sensitivityInputFile of the zeroToParSensiConversion analytic names it. The sensitivity analytic writes the file, so the name here is the name that analytic gives it, and the two cannot differ.', 109, true, 'sensitivity.sensitivityOutputFile')
        ) as t (code, analytic_type_code, ore_parameter, direction, kind, format, xsd_file, configuration_type_code, name_pattern, sample_count, sample_total, description, display_order, is_default, produced_by_file_type_code)
    loop
        if not exists (
            select 1 from ores_reporting_file_types_tbl
            where tenant_id = v_sys_tenant and code = r.code
              and valid_to = ores_utility_infinity_timestamp_fn()
        ) then
            insert into ores_reporting_file_types_tbl (
                code, analytic_type_code, ore_parameter, direction, kind, format, xsd_file, configuration_type_code, name_pattern, sample_count, sample_total, description, display_order, is_default, produced_by_file_type_code,
                tenant_id, version, modified_by, change_reason_code, change_commentary
            ) values (
                r.code, r.analytic_type_code, r.ore_parameter, r.direction, r.kind, r.format, r.xsd_file, r.configuration_type_code, r.name_pattern, r.sample_count, r.sample_total, r.description, r.display_order, r.is_default, r.produced_by_file_type_code,
                v_sys_tenant, 0, current_user, 'system.initial_load', 'Seed file type: ' || r.code
            );
            raise debug 'Created file type: %', r.code;
        else
            raise debug 'File type already exists: %', r.code;
        end if;
    end loop;
end $$;
